            k=16
            idx=np.argpartition(M,k-1,axis=1)[:,:k]
            rows=np.repeat(np.arange(n),k)
            S=csr_matrix((M[rows,idx.ravel()],(rows,idx.ravel())),shape=(n,n))
            try: r,c=min_weight_full_bipartite_matching(S)
            except ValueError:
                from scipy.optimize import linear_sum_assignment
                r,c=linear_sum_assignment(M)
            G=np.zeros((n,n)); G[r,c]=a[0]
            return {'transport_plan':G}
